{"explanation":"The discriminant Δ = b² − 4ac is the expression under the square root in the quadratic formula. If Δ > 0, the parabola crosses the x-axis twice; if Δ = 0, it touches the axis at one repeated real root; and if Δ < 0, it never meets the axis, so there are no real roots. Move the slider to explore these cases for x² − 2x + c.","manimCode":"const heading = new Text({ text: 'The discriminant counts real roots', color: WHITE, fontSize: 32 });
heading.moveTo([0, 3.2, 0]);
const formula = new MathTex({ latex: 'ax^2+bx+c=0\quad(a\ne0),\qquad \Delta=b^2-4ac' });
await formula.waitForRender();
formula.scale(0.8);
formula.moveTo([0, 2.5, 0]);
scene.add(heading, formula);

const ax = new Axes({ xRange: [-2, 4, 1], yRange: [-3, 6, 1], xLength: 7, yLength: 4.4, tips: false });
ax.moveTo([-2, -0.3, 0]);
const zeroLine = new Line({ start: ax.c2p(-2, 0), end: ax.c2p(4, 0), color: WHITE });
zeroLine.setStrokeWidth(3);
const axisCaption = new Text({ text: 'x-axis: y = 0', color: GRAY, fontSize: 18 });
axisCaption.moveTo([-4.4, -2.8, 0]);
scene.add(ax, zeroLine, axisCaption);

const example = new MathTex({ latex: 'y=x^2-2x+c' });
await example.waitForRender();
example.scale(0.8);
example.moveTo([3.8, 2.05, 0]);
scene.add(example);

let constant = 0;
let curve = null;
let markers = [];
let readouts = [];
function refresh(value) {
  constant = value;
  if (curve) scene.remove(curve);
  markers.forEach(m => scene.remove(m));
  readouts.forEach(m => scene.remove(m));
  markers = [];
  readouts = [];
  const delta = 4 - 4 * constant;
  const tangent = Math.abs(delta) < 0.000001;
  const tint = tangent ? YELLOW : delta > 0 ? GREEN : RED;
  const span = Math.sqrt(6.5 - constant);
  curve = ax.plot(x => x * x - 2 * x + constant, {
    xRange: [Math.max(-2, 1 - span), Math.min(4, 1 + span)],
    color: BLUE,
    numSamples: 240
  });
  curve.setStrokeWidth(4);
  scene.add(curve);
  if (delta >= -0.000001) {
    const distance = Math.sqrt(Math.max(0, 1 - constant));
    const roots = tangent ? [1] : [1 - distance, 1 + distance];
    roots.forEach(root => {
      const marker = new Dot({ point: ax.c2p(root, 0), color: tint });
      markers.push(marker);
      scene.add(marker);
    });
  }
  const rows = [
    { str: 'c = ' + constant.toFixed(2), y: 1.4, color: WHITE, size: 25 },
    { str: 'Δ = 4 − 4c = ' + delta.toFixed(2), y: 0.8, color: tint, size: 24 },
    { str: tangent ? 'Δ = 0: one real root' : delta > 0 ? 'Δ > 0: two real roots' : 'Δ < 0: no real roots', y: 0.1, color: tint, size: 23 },
    { str: tangent ? 'Touches the x-axis' : delta > 0 ? 'Crosses the x-axis twice' : 'Never meets the x-axis', y: -0.5, color: WHITE, size: 19 },
    { str: tangent ? 'x = 1 (repeated)' : delta > 0 ? 'x = ' + (1 - Math.sqrt(1 - constant)).toFixed(2) + ', ' + (1 + Math.sqrt(1 - constant)).toFixed(2) : 'The roots are complex', y: -1.1, color: GRAY, size: 20 }
  ];
  rows.forEach(row => {
    const label = new Text({ text: row.str, color: row.color, fontSize: row.size });
    label.moveTo([3.8, row.y, 0]);
    readouts.push(label);
    scene.add(label);
  });
}
refresh(0);
const instruction = new Text({ text: 'Change c to move the parabola up or down. The turning point reaches the axis at c = 1.', color: GRAY, fontSize: 19 });
instruction.moveTo([0, -3.3, 0]);
scene.add(instruction);
await scene.wait(1.5);
refresh(1);
await scene.wait(1.5);
refresh(2);
await scene.wait(1.5);
refresh(0);

const controls = new Controls(scene, { position: 'bottom-right', width: 260 });
controls.addSlider({ label: 'Constant c', min: -1, max: 3, value: 0, step: 0.05, onChange: value => refresh(value) });
controls.addButton({ label: 'Two real roots: c = 0', onClick: () => refresh(0) });
controls.addButton({ label: 'Repeated root: c = 1', onClick: () => refresh(1) });
controls.addButton({ label: 'No real roots: c = 2', onClick: () => refresh(2) });
await scene.wait(999999);"}

